INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f2fd495e-66d9-47d5-bab8-ae3648536dcb', 'vocabulary', '気持ち', '気持ち', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Energi yang Anda simpan di tubuh Anda adalah perasaan Anda. Bentuknya bisa bermacam-macam. Perasaan baik, perasaan buruk, "perasaan aneh" itu.', 'Energi yang Anda simpan di tubuh Anda adalah perasaan Anda. Bentuknya bisa bermacam-macam. Perasaan baik, perasaan buruk, "perasaan aneh" itu.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
