INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('712bd47a-1255-4b17-970d-109e7a8c9b4e', 'しかし、この世界にはどちらもありません。', 'Namun, keduanya tidak ada di dunia ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('712bd47a-1255-4b17-970d-109e7a8c9b4e', 'ふじ山は世界いさんにとうろくされています。', 'Gunung Fuji terdaftar sebagai Situs Warisan Dunia.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('712bd47a-1255-4b17-970d-109e7a8c9b4e', 'あいつは自分の世界に閉じこもっていて、そこから出てこようとしないんだ。', 'Dia hidup di dunianya sendiri dan tidak ingin meninggalkannya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5d0d1e78-685d-4bb4-9784-aaea03f8fd50', 'vocabulary', '発売', '発売', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Anda ingin barang-barang berangkat dari toko Anda sehingga Anda harus menjualnya. Anda menjual semua ini. Anda menjual barang-barang ini.', 'Anda ingin barang-barang berangkat dari toko Anda sehingga Anda harus menjualnya. Anda menjual semua ini. Anda menjual barang-barang ini.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
