INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5d0d1e78-685d-4bb4-9784-aaea03f8fd50', 'この夏、Tofuguから、「ベーコンとおこのみやきのチーズタルト」が発売されることが決定しました！', 'Kami memutuskan untuk menjual kue tar bacon dan keju okonomiyaki dari Tofugu musim panas ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5d0d1e78-685d-4bb4-9784-aaea03f8fd50', 'コウイチのつめのあかをせんじたポートランド名物トーフグ茶がトーフグのウェブサイトででぜっさん発売中です！', 'Teh Tofugu yang terkenal di Portland, dengan kotoran kuku Koichi, kini dijual di situs Tofugu!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5d0d1e78-685d-4bb4-9784-aaea03f8fd50', 'トーフグのデート用抱きまくらが発売されるのが待ち遠しい。', 'Saya tidak sabar menunggu bantal kencan Tofugu dijual.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ce222b7e-155f-4b52-a04e-9b9430b48ded', 'vocabulary', '発音', '発音', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Suara yang keluar dari mulutmu adalah kamu sedang berbicara. Bayangkan diri Anda mengucapkan sesuatu dan kata-kata yang keluar dari mulut Anda. Mereka ditekuk dengan cara berbeda dan memiliki warna berbeda, menonjolkan pengucapan Anda atas kata dan frasa tertentu.', 'Suara yang keluar dari mulutmu adalah kamu sedang berbicara. Bayangkan diri Anda mengucapkan sesuatu dan kata-kata yang keluar dari mulut Anda. Mereka ditekuk dengan cara berbeda dan memiliki warna berbeda, menonjolkan pengucapan Anda atas kata dan frasa tertentu.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
