INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ce222b7e-155f-4b52-a04e-9b9430b48ded', 'このたんごの発音を教えてください。', 'Tolong ajari saya pengucapan kata ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ce222b7e-155f-4b52-a04e-9b9430b48ded', 'テイラーさんは日本ごの発音がとても上手ですね。', 'Taylor, pengucapan bahasa Jepangmu sangat bagus.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ce222b7e-155f-4b52-a04e-9b9430b48ded', 'わあ！スペイン語の小さな家って言葉の発音、日本語の「お腹すいた」にめちゃくちゃ似てる！', 'Wow, pengucapan kata "una casita" dalam bahasa Spanyol terdengar mirip dengan "Aku lapar" dalam bahasa Jepang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8c8aa4a0-9aeb-4cfe-bf2f-1e12d5dc6112', 'vocabulary', '発見', '発見', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Anda berangkat dari rumah Anda menuju alam baka. Anda akan melihat hal-hal yang tak terlihat, dan mudah-mudahan mendapatkan penemuan hebat.', 'Anda berangkat dari rumah Anda menuju alam baka. Anda akan melihat hal-hal yang tak terlihat, dan mudah-mudahan mendapatkan penemuan hebat.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
