INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8c8aa4a0-9aeb-4cfe-bf2f-1e12d5dc6112', '自たくのベランダで、イモムシを発見しました。', 'Saya menemukan cacing tanduk di balkon saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8c8aa4a0-9aeb-4cfe-bf2f-1e12d5dc6112', 'がんは、早き発見することがひじょうに重ようです。', 'Sangat penting untuk melakukan deteksi dini terhadap kanker.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8c8aa4a0-9aeb-4cfe-bf2f-1e12d5dc6112', 'Facebookでお金を稼ぐ方法を発見したぜ。しかも超簡単なの。まず、アカウント設定に行くだろ、それからアカウントを停止して、仕事に行くんだ！', 'Saya menemukan cara menghasilkan uang dari Facebook. Itu mudah. Buka saja pengaturan akun Anda, nonaktifkan akun Anda, dan mulai bekerja.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f892f5bd-3f09-427d-9d7b-1c149afa7488', 'vocabulary', '送る', '送る', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri berarti mengirim, dan versi vocab verbanya adalah mengirim sesuatu. Jika objek verba ini adalah orang, artinya “mengutus” dalam arti mengantar seseorang, mungkin ke stasiun, atau ke pintu.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri berarti mengirim, dan versi vocab verbanya adalah mengirim sesuatu. Jika objek verba ini adalah orang, artinya “mengutus” dalam arti mengantar seseorang, mungkin ke stasiun, atau ke pintu.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f892f5bd-3f09-427d-9d7b-1c149afa7488', 'Untuk Mengirim Sesuatu', true) ON CONFLICT DO NOTHING;
