INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f892f5bd-3f09-427d-9d7b-1c149afa7488', 'スミスさんに手紙を送りました。', 'Saya mengirim surat kepada Tuan Smith.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f892f5bd-3f09-427d-9d7b-1c149afa7488', '後で写しんLINEで送るね。', 'Saya akan mengirimkan fotonya nanti di LINE.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f892f5bd-3f09-427d-9d7b-1c149afa7488', '遅くなったね。今日はここまでにしよう。家まで送るよ。', 'Ini sudah larut. Anggap saja ini sehari. Aku akan mengantarmu pulang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('701f1024-824c-4558-a012-a95606c96d7b', 'vocabulary', '重い', '重い', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat dari berat? Ini juga berat.', 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat dari berat? Ini juga berat.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('701f1024-824c-4558-a012-a95606c96d7b', 'Berat', true) ON CONFLICT DO NOTHING;
