INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('701f1024-824c-4558-a012-a95606c96d7b', 'そのにもつは重そうですね。', 'Bagasinya terlihat berat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('701f1024-824c-4558-a012-a95606c96d7b', 'この車、重すぎてうでがもげそう。', 'Mobil ini sangat berat hingga lenganku hampir lepas.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('701f1024-824c-4558-a012-a95606c96d7b', '「足を踏んでしまってごめんなさい。」「ちょっと重かったけど、どうってことないよ。」', '"Maaf aku menginjak kakimu." "Tidak masalah. Agak berat, tapi tidak ada kerusakan apa pun."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('dc20b25c-74b9-46df-8960-e69bc810f253', 'vocabulary', '体重', '体重', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Berapa berat badanmu? Cari tahu itu dan Anda akan mendapatkan berat badan Anda.', 'Berapa berat badanmu? Cari tahu itu dan Anda akan mendapatkan berat badan Anda.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
