INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('9c5f20ad-d89f-41e6-ae50-99029f2ae6ea', 'ようふう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9c5f20ad-d89f-41e6-ae50-99029f2ae6ea', '今日の夕食は、洋風ポトフです。', 'Makan malam malam ini adalah pot‐au‐feu gaya Barat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9c5f20ad-d89f-41e6-ae50-99029f2ae6ea', '洋風なかんじのオシャレな曲が、洋風のカフェでながれていた。', 'Lagu gaya barat yang halus dimainkan di kafe gaya Barat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9c5f20ad-d89f-41e6-ae50-99029f2ae6ea', '私の家は、家具を全て洋風に揃えているので、畳はありません。', 'Rumah saya seluruhnya dilengkapi dengan gaya Barat, jadi tidak ada tikar tatami.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('877256a0-8066-4ac5-9240-5bffb7ef14fe', 'vocabulary', '洋服', '洋服', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Pakaian gaya barat hanyalah pakaian Barat (atau pakaian gaya Barat). Namun saat ini, karena orang Jepang selalu memakai pakaian Barat, kami menggunakannya hanya untuk memaksudkan pakaian. Kami membicarakan hal-hal yang bukan kimono, dll.', 'Pakaian gaya barat hanyalah pakaian Barat (atau pakaian gaya Barat). Namun saat ini, karena orang Jepang selalu memakai pakaian Barat, kami menggunakannya hanya untuk memaksudkan pakaian. Kami membicarakan hal-hal yang bukan kimono, dll.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
