INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('877256a0-8066-4ac5-9240-5bffb7ef14fe', '洋服を貸してくれて有難う。', 'Terima kasih telah meminjamkanku pakaianmu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('877256a0-8066-4ac5-9240-5bffb7ef14fe', '和服にしようか洋服にしようかまよってます。', 'Saya kesulitan menentukan pakaian mana yang akan saya pakai, gaya Jepang atau gaya Barat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('877256a0-8066-4ac5-9240-5bffb7ef14fe', '早く洋服を着ないと、学校に遅れるわよ。', 'Kamu harus segera berpakaian atau kamu akan terlambat ke sekolah.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e37969d1-e86e-428d-b6d6-82d1520d27c5', 'vocabulary', '洋食', '洋食', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Makanan Barat adalah makanan Barat. Mmmm, itu hamburger.', 'Makanan Barat adalah makanan Barat. Mmmm, itu hamburger.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
