INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e37969d1-e86e-428d-b6d6-82d1520d27c5', 'Western Style Food', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('e37969d1-e86e-428d-b6d6-82d1520d27c5', 'ようしょく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e37969d1-e86e-428d-b6d6-82d1520d27c5', 'この洋食レストランは、有名なすし屋が共同して立ち上げたものです。', 'Restoran western food ini dibuat bekerjasama dengan restoran sushi ternama.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e37969d1-e86e-428d-b6d6-82d1520d27c5', 'いわゆる昔ながらの洋食屋さんで、バイトをしています。', 'Saya bekerja paruh waktu di sebuah restoran keluarga Barat yang kuno.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e37969d1-e86e-428d-b6d6-82d1520d27c5', 'ええっ！あそこのレストランで洋食ランチセットを食べたの？ははは。どおりでまだお腹がいっぱいなはずだわ。', 'Oh, apakah kamu sudah makan set makan siang ala barat di restoran itu? Ha ha ha. Pantas saja Anda masih merasa kenyang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f02db5de-5125-4f2f-ad94-540b59e115f4', 'vocabulary', '洋室', '洋室', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Kamar bergaya Barat adalah kamar bergaya Barat. Kita sedang membicarakan sesuatu yang bukan ruangan yang dipenuhi tikar tatami. Senang mengetahui kata ini jika kamu menginap di hotel atau ryokan dan memilih untuk tidak tidur di futon, dll.', 'Kamar bergaya Barat adalah kamar bergaya Barat. Kita sedang membicarakan sesuatu yang bukan ruangan yang dipenuhi tikar tatami. Senang mengetahui kata ini jika kamu menginap di hotel atau ryokan dan memilih untuk tidak tidur di futon, dll.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f02db5de-5125-4f2f-ad94-540b59e115f4', 'Kamar Gaya Barat', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('f02db5de-5125-4f2f-ad94-540b59e115f4', 'ようしつ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f02db5de-5125-4f2f-ad94-540b59e115f4', 'コウイチの発言で、洋室にいた全いんがこおりついてしまった。', 'Saat Koichi melontarkan komentar itu, semua orang di ruangan bergaya barat membeku.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f02db5de-5125-4f2f-ad94-540b59e115f4', 'この洋室、はじめて来た場所なのに、なんだかよく知ってる部屋のような気がする。', 'Anehnya, ruangan bergaya barat ini tampak familier, meski aku tahu aku belum pernah ke sini sebelumnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f02db5de-5125-4f2f-ad94-540b59e115f4', '私の部屋は六畳の洋室で、壁の色は私の好きな水色です。', 'Kamar saya adalah kamar bergaya barat, berukuran sekitar sepuluh meter persegi, dengan warna favorit saya biru muda di dinding.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c7799672-d771-4b09-93e7-0838e625b566', 'vocabulary', '風', '風', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('c7799672-d771-4b09-93e7-0838e625b566', 'Angin', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('c7799672-d771-4b09-93e7-0838e625b566', 'かぜ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c7799672-d771-4b09-93e7-0838e625b566', '外では、つめたい風がふいていました。', 'Angin dingin bertiup di luar.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c7799672-d771-4b09-93e7-0838e625b566', '風が強くなってきましたね。', 'Angin semakin kencang, bukan?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c7799672-d771-4b09-93e7-0838e625b566', '風が彼女のカツラを吹き飛ばした時に、私は自分が坊主の女性にとても魅力を感じることに気が付きました。', 'Ketika angin meniup wig dari kepalanya, saya menyadari bahwa saya sangat tertarik pada wanita botak.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('261e0f59-e3f1-41df-9051-5b2235ee2987', 'vocabulary', '思い出', '思い出', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Apakah Anda ingat kata 思う? Artinya "berpikir". Apa yang Anda pikirkan sungguh keluar—keluar dari kepala Anda! Anda sedang mengingat kenangan dan/atau kenangan.', 'Apakah Anda ingat kata 思う? Artinya "berpikir". Apa yang Anda pikirkan sungguh keluar—keluar dari kepala Anda! Anda sedang mengingat kenangan dan/atau kenangan.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('261e0f59-e3f1-41df-9051-5b2235ee2987', 'Sebuah Kenangan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('261e0f59-e3f1-41df-9051-5b2235ee2987', 'Memories', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('261e0f59-e3f1-41df-9051-5b2235ee2987', 'Memory', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('261e0f59-e3f1-41df-9051-5b2235ee2987', 'おもいで', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('261e0f59-e3f1-41df-9051-5b2235ee2987', '思い出って、むねにそっとしまっておくものなんじゃないの？', 'Bukankah kenangan adalah hal yang kau simpan dengan aman di dadamu?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('261e0f59-e3f1-41df-9051-5b2235ee2987', '子どものころ、日がくれるまで友だちとあそんでいたことは、今となってはとてもなつかしいいい思い出です。今はもうかん全ボッチですからね。', 'Aku biasa bermain dengan teman-temanku sampai hari gelap. Benar-benar kenangan nostalgia yang luar biasa sekarang terutama karena saya tidak punya teman lagi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('261e0f59-e3f1-41df-9051-5b2235ee2987', '私のお父さんが毎週日曜日の朝にチョコレートでコーティングされたベーコンを作ってくれたのは、とてもいい思い出です。', 'Ayah saya membuatkan bacon berlapis coklat untuk kami setiap Minggu pagi adalah kenangan indah saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('65435859-1ba4-48b9-97f6-e100e5632881', 'vocabulary', '思い出す', '思い出す', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Anda tahu bahwa 思う artinya berpikir (jadi 思い adalah pemikiran). Anda juga tahu bahwa 出す artinya menghapus. Jadi, ketika Anda menghilangkan sebuah pikiran, Anda sedang mengingat sesuatu. Ini merupakan kata kerja, jadi bentuk kata kerja mengingat sesuatu adalah mengingat.', 'Anda tahu bahwa 思う artinya berpikir (jadi 思い adalah pemikiran). Anda juga tahu bahwa 出す artinya menghapus. Jadi, ketika Anda menghilangkan sebuah pikiran, Anda sedang mengingat sesuatu. Ini merupakan kata kerja, jadi bentuk kata kerja mengingat sesuatu adalah mengingat.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('65435859-1ba4-48b9-97f6-e100e5632881', 'Untuk Diingat', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('65435859-1ba4-48b9-97f6-e100e5632881', 'To Recall', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('65435859-1ba4-48b9-97f6-e100e5632881', 'おもいだす', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('65435859-1ba4-48b9-97f6-e100e5632881', 'わたしは、家を出る時、いつも家の前でひかれた子犬のことを思い出します。', 'Saat aku keluar rumah, aku selalu teringat anak anjingku yang tertabrak di depan rumah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('65435859-1ba4-48b9-97f6-e100e5632881', '四けたのあんしょう番号が思い出せなくて、めっちゃあせったよ。', 'Saya sangat panik karena saya tidak dapat mengingat 4 digit kode PIN saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('65435859-1ba4-48b9-97f6-e100e5632881', '人に思い出してもらう一番の方法は、その人たちからお金を借りることだ。', 'Cara terbaik untuk membuat seseorang mengingat Anda adalah dengan meminjam uang dari mereka.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7c52342e-5d9f-4aed-b222-7db83a9bfaab', 'vocabulary', '青空', '青空', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Ini hanyalah langit biru (alias langit biru!).', 'Ini hanyalah langit biru (alias langit biru!).') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7c52342e-5d9f-4aed-b222-7db83a9bfaab', 'Langit Biru', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('7c52342e-5d9f-4aed-b222-7db83a9bfaab', 'あおぞら', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7c52342e-5d9f-4aed-b222-7db83a9bfaab', '青空のせいで海は青いの？', 'Apakah laut berwarna biru karena langit biru?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7c52342e-5d9f-4aed-b222-7db83a9bfaab', '未来の子どもたちに、今と同じくらいうつくしい青空をのこしてあげましょうよ。', 'Biarlah generasi penerus kita memiliki langit yang indah seperti kita.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7c52342e-5d9f-4aed-b222-7db83a9bfaab', '今日は一日中晴れて、青空が広がっていました。', 'Hari ini cerah sepanjang hari dan langit biru berada di atas kami.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5e10b6c8-3f61-4408-aa01-95b4c26c5aae', 'vocabulary', '待ちぼうけ', '待ちぼうけ', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Dengan 待ち kamu tahu kamu sedang menunggu, tapi apa itu ぼうけ? Ternyata itu versi panjang dari ボケ yang artinya bodoh. Pada dasarnya, dalam hal ini Anda adalah seorang idiot yang menunggu. Mengapa? karena kamu sudah berdiri.', 'Dengan 待ち kamu tahu kamu sedang menunggu, tapi apa itu ぼうけ? Ternyata itu versi panjang dari ボケ yang artinya bodoh. Pada dasarnya, dalam hal ini Anda adalah seorang idiot yang menunggu. Mengapa? karena kamu sudah berdiri.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('5e10b6c8-3f61-4408-aa01-95b4c26c5aae', 'Berdiri', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('5e10b6c8-3f61-4408-aa01-95b4c26c5aae', 'Waiting In Vain', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('5e10b6c8-3f61-4408-aa01-95b4c26c5aae', 'まちぼうけ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5e10b6c8-3f61-4408-aa01-95b4c26c5aae', '返事を待っていましたが、待ちぼうけを食らいました。', 'Sia-sia aku menunggu jawaban.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5e10b6c8-3f61-4408-aa01-95b4c26c5aae', 'おかげで、さびれたえきで、一時間も待ちぼうけをする羽目になったよ。', 'Berkat itu, saya berdiri sekitar satu jam di stasiun terpencil.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5e10b6c8-3f61-4408-aa01-95b4c26c5aae', '彼が待ちぼうけを食らったと思わないように、明日の会議が中止になったことを伝えてあげてくれるかな？', 'Bisakah Anda memberi tahu dia bahwa konferensi besok telah dibatalkan sehingga dia tidak akan merasa seperti telah ditentang?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d19bd2bc-395f-4309-b354-1e004d66837a', 'vocabulary', '見送る', '見送る', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Semoga Anda sudah mengetahui kata 見る dan 送る. Di sini Anda "melihat" "pengiriman". Anda mengantar seseorang pergi, jadi kata kerjanya adalah mengantar. Ini juga bisa berarti menunda atau meneruskan, karena ini seolah-olah Anda hanya secara pasif melihat seseorang (atau sesuatu) pergi daripada mengambil tindakan dan pergi bersama mereka.', 'Semoga Anda sudah mengetahui kata 見る dan 送る. Di sini Anda "melihat" "pengiriman". Anda mengantar seseorang pergi, jadi kata kerjanya adalah mengantar. Ini juga bisa berarti menunda atau meneruskan, karena ini seolah-olah Anda hanya secara pasif melihat seseorang (atau sesuatu) pergi daripada mengambil tindakan dan pergi bersama mereka.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('d19bd2bc-395f-4309-b354-1e004d66837a', 'Untuk Melihat', true) ON CONFLICT DO NOTHING;
