INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('6a7c6a9a-db63-4066-aeba-56e643950f82', 'うつる', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6a7c6a9a-db63-4066-aeba-56e643950f82', 'スクリーンに社内用しりょうが映っています。', 'Dokumen internal perusahaan sedang diproyeksikan di layar.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6a7c6a9a-db63-4066-aeba-56e643950f82', '鏡に映った自分のかおを見て、「なんて美しいんだ」と毎日思っています。', 'Melihat wajahku sendiri yang terpantul di cermin aku merasakan “betapa cantiknya wajahku” setiap hari.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6a7c6a9a-db63-4066-aeba-56e643950f82', 'コウイチは湖の水面に映る美しい山に感動し、ホロリと涙を流した。', 'Setetes air mata mengalir di pipi Koichi saat melihat indahnya pegunungan terpantul di permukaan danau.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7a3a3549-45ae-45f5-a21b-7384c0f25c01', 'vocabulary', '映画', '映画', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Ini adalah gambar yang menggunakan refleksi untuk memproyeksikan gambar. Dan, gambarnya bergerak! Sungguh menakjubkan! Apa ini? Itu adalah sebuah film.', 'Ini adalah gambar yang menggunakan refleksi untuk memproyeksikan gambar. Dan, gambarnya bergerak! Sungguh menakjubkan! Apa ini? Itu adalah sebuah film.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
