INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('4629d5db-baaa-497f-bfb4-f543702141a0', 'ひる', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4629d5db-baaa-497f-bfb4-f543702141a0', '今日の昼、あそこの定食屋でお昼一しょに食べようよ。', 'Mengapa kita tidak makan siang bersama di restoran itu saat istirahat makan siang hari ini?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4629d5db-baaa-497f-bfb4-f543702141a0', '目ざまし時計が鳴らなくて、起きたらすでに昼だった。', 'Alarmku tidak berbunyi dan hari sudah siang ketika aku bangun.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4629d5db-baaa-497f-bfb4-f543702141a0', '今から一時間昼休憩を取るので、電話は取り次がないようにしてください。', 'Saya akan istirahat makan siang selama satu jam, jadi tolong tahan telepon saya.') ON CONFLICT DO NOTHING;
