INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9df50609-4251-4b54-bee0-ac0b1c6f9d0a', '秋はわたしの一番好きなきせつです。', 'Musim gugur adalah musim favorit saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9df50609-4251-4b54-bee0-ac0b1c6f9d0a', '秋と言えば何を思いうかべますか。わたしはやっぱり食よくの秋ですね。', 'Ketika Anda mendengar "jatuh", apa yang Anda kaitkan dengannya? Seperti yang mungkin bisa Anda bayangkan, saya memang memikirkan "nafsu makan menurun".') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9df50609-4251-4b54-bee0-ac0b1c6f9d0a', 'はぁ？まだこの秋に一回ご飯食べに行っただけなの？あんた頭イッちゃってるんじゃないの？どう考えても彼氏って呼ぶのはおかしいでしょ。それは付き合ってるとは言えないと思うよ。', 'Apa? Sejauh ini Anda baru pergi makan malam bersamanya pada musim gugur ini? Apakah kamu sudah kehilangan akal sehat? Tidakkah menurutmu aneh rasanya memanggilnya pacarmu? Menurutku kamu tidak bisa bilang kalau kamu berkencan dengannya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('71898150-a2d4-4f55-9735-32da8ceb7d15', 'vocabulary', '時計', '時計', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Sesuatu yang memberi Anda pengukuran waktu adalah jam tangan atau jam. Kebanyakan orang sekarang memilikinya di ponsel mereka, bukan di pergelangan tangan mereka.', 'Sesuatu yang memberi Anda pengukuran waktu adalah jam tangan atau jam. Kebanyakan orang sekarang memilikinya di ponsel mereka, bukan di pergelangan tangan mereka.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
