INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('14a7f30c-cbe7-4de8-85ee-bd72fa5d848e', '夏休みに海に行こうと計画しています。', 'Kami berencana pergi ke pantai selama liburan musim panas.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('14a7f30c-cbe7-4de8-85ee-bd72fa5d848e', '計画を立てるのは大好きなんですけど、計画したことを実行するのはきらいなんです。', 'Aku suka membuat rencana, tapi aku tidak suka melaksanakan apa yang sudah aku rencanakan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('14a7f30c-cbe7-4de8-85ee-bd72fa5d848e', 'もし俺たちがエッフェル塔を盗むというなら、かなりしっかりした計画を練る必要がある。', 'Jika kita ingin mencuri Menara Eiffel, kita harus mempunyai rencana yang sangat bagus.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0779c47f-8a17-4cd7-b708-791ec38502b3', 'vocabulary', '下品', '下品', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Yang di bawah normalnya produk adalah barang tiruan yang murah dan kualitas barang yang jelek. Barang-barang ini sangat kasar dan vulgar dalam pembuatan dan desainnya. Begitu banyak vulgar!', 'Yang di bawah normalnya produk adalah barang tiruan yang murah dan kualitas barang yang jelek. Barang-barang ini sangat kasar dan vulgar dalam pembuatan dan desainnya. Begitu banyak vulgar!') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
