INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('06e52c38-1122-478b-a515-2787c3d84a21', 'この箱庭の作品は、マッチ箱で作られています。', 'Karya taman mini ini terbuat dari kotak korek api.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('06e52c38-1122-478b-a515-2787c3d84a21', 'トーフグオフィスの入り口にあるヘンテコな像は、コウイチの十五才の時の作品ですよ。', 'Patung aneh di pintu masuk kantor Tofugu adalah karya Koichi ketika ia berusia lima belas tahun.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('06e52c38-1122-478b-a515-2787c3d84a21', '久々にいい作品に出会ったわ。進撃の巨人は、私の好きなアニメの歴代三位に入るんじゃないかってくらい良かったよ。マジでお薦めするわ。', 'Sudah lama sejak saya menemukan karya yang saya sukai. Attack on Titan sangat bagus sehingga mungkin menjadi salah satu dari tiga anime teratas saya. Saya sangat merekomendasikannya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f4b52089-42f2-4bad-b001-49ed128fbbad', 'vocabulary', '品', '品', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Ini sama dengan kanji, setidaknya dalam arti artikel atau barang, artinya Anda bisa menggunakan kata ini untuk mengartikan artikel atau barang.', 'Ini sama dengan kanji, setidaknya dalam arti artikel atau barang, artinya Anda bisa menggunakan kata ini untuk mengartikan artikel atau barang.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
