INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4977fd3a-ae83-4257-98fd-ac3fd408e33a', 'よくその本屋に行きます。', 'Saya sering pergi ke toko buku itu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4977fd3a-ae83-4257-98fd-ac3fd408e33a', 'この本屋には、ツアーガイドブックがたく山おいてあります。', 'Toko buku ini memiliki banyak sekali buku panduan wisata.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4977fd3a-ae83-4257-98fd-ac3fd408e33a', '本屋のレジでアルバイトをしています。', 'Saya bekerja paruh waktu di kasir toko buku.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d1277aaa-0fb8-4d90-b21b-4e6287b692f4', 'vocabulary', '発売中', '発売中', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Ada 発売, yang artinya "dijual", lalu ada 中 yang berada di tengah. Suatu barang yang sedang dijual sekarang dijual, sekarang di toko atau dengan kata lain sekarang tersedia. Anda akan melihat ini untuk barang-barang yang baru saja dirilis atau ketika penjaga toko ingin memberi tahu Anda bahwa mereka sedang menjual sesuatu sekarang, akhirnya, atau apa pun.', 'Ada 発売, yang artinya "dijual", lalu ada 中 yang berada di tengah. Suatu barang yang sedang dijual sekarang dijual, sekarang di toko atau dengan kata lain sekarang tersedia. Anda akan melihat ini untuk barang-barang yang baru saja dirilis atau ketika penjaga toko ingin memberi tahu Anda bahwa mereka sedang menjual sesuatu sekarang, akhirnya, atau apa pun.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
