INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('14f04faa-8676-4826-bf8f-c9da9b822a42', '姉のいえに行くところです。', 'Aku baru saja akan pergi ke rumah kakak perempuanku.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('14f04faa-8676-4826-bf8f-c9da9b822a42', 'わたしは、姉の五ばいのりょうの本をもっています。', 'Saya mempunyai buku lima kali lebih banyak daripada kakak perempuan saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('14f04faa-8676-4826-bf8f-c9da9b822a42', '姉はスチュワーデスをしています。', 'Kakak perempuan saya bekerja sebagai pramugari.') ON CONFLICT DO NOTHING;
