INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('481fcaec-23cb-4a6a-88ff-badf903f8ce7', 'きょう室に入ってください。', 'Silakan masuk ke kelas.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('481fcaec-23cb-4a6a-88ff-badf903f8ce7', 'このゲーム、むずかしすぎるよ。このめんで、１５６９号室まで行くには、どうがんばってもじかんが足りないんだ。', 'Permainan ini terlalu sulit. Saya tidak pernah punya cukup waktu untuk mencapai kamar nomor 1569 pada tahap ini tidak peduli seberapa keras saya berusaha.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('481fcaec-23cb-4a6a-88ff-badf903f8ce7', '保健室で眠っていました。', 'Aku sedang tidur di ruang kesehatan sekolah.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('44188a82-23b3-42ac-9cec-8a822998d9ff', 'vocabulary', '思わず', '思わず', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Ini adalah versi kata keterangan dari kanji think. Anda tidak bisa tidak berpikir, Anda melakukannya secara tidak sengaja. Jadi letakkan ini di depan hal-hal yang menunjukkan bahwa Anda melakukannya tanpa disengaja.', 'Ini adalah versi kata keterangan dari kanji think. Anda tidak bisa tidak berpikir, Anda melakukannya secara tidak sengaja. Jadi letakkan ini di depan hal-hal yang menunjukkan bahwa Anda melakukannya tanpa disengaja.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
