INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('12e979f1-b555-4071-a421-3faafd49b878', 'それはとても急な知らせだったので、彼女は驚いた。', 'Itu adalah berita yang sangat mendadak sehingga dia terkejut.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('12e979f1-b555-4071-a421-3faafd49b878', '急な仕事を引き受けちゃったので、今日のおむかえはおそくなります。', 'Aku mengambil tugas mendesak, jadi aku harus menjemput anakku lebih lambat dari biasanya hari ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('12e979f1-b555-4071-a421-3faafd49b878', '急な依頼ですみません。どうしても断れないお客様からの急ぎの注文だったんです。', 'Maaf atas permintaan yang tiba-tiba. Kami harus menerima pesanan mendesak dari pelanggan yang tidak dapat kami tolak.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('21f3ef72-3e02-4829-a03b-cdd77fc7caaa', 'vocabulary', '台風', '台風', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Mesin yang memompa angin dapat mengalami kegagalan fungsi dan menghasilkan terlalu banyak sehingga menyebabkan angin topan. Ini adalah mesin yang sangat kuat untuk mampu menggerakkan angin sebanyak itu.', 'Mesin yang memompa angin dapat mengalami kegagalan fungsi dan menghasilkan terlalu banyak sehingga menyebabkan angin topan. Ini adalah mesin yang sangat kuat untuk mampu menggerakkan angin sebanyak itu.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
