INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d4cb26d2-e9c7-4438-be48-5f45a2ffc011', '今日、屋上でバーベキューをします。', 'Kami mengadakan barbekyu di atap hari ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d4cb26d2-e9c7-4438-be48-5f45a2ffc011', '夜きん明けにもかかわらず、屋上できんトレをしました。', 'Saya berolahraga di rooftop pada pagi hari meskipun saya bekerja pada shift malam.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d4cb26d2-e9c7-4438-be48-5f45a2ffc011', '屋上に上がって、天からふり注ぐ星の光を一緒にあびないかい？', 'Mengapa kita tidak naik ke atap rumah dan melihat cahaya bintang yang bersinar dari langit?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5ef8b2ac-9520-4b8b-8818-649234b510f9', 'vocabulary', '何度', '何度', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Jika seseorang bertanya kepada Anda kejadian apa atau derajat apa, mereka sebenarnya mencoba menanyakan berapa kali sesuatu terjadi. Terkadang mereka juga menanyakan berapa suhunya.', 'Jika seseorang bertanya kepada Anda kejadian apa atau derajat apa, mereka sebenarnya mencoba menanyakan berapa kali sesuatu terjadi. Terkadang mereka juga menanyakan berapa suhunya.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
