INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5ef8b2ac-9520-4b8b-8818-649234b510f9', '人生には本当に大切なしゅん間が何度かおとずれる。', 'Kita semua memiliki momen yang sangat penting, beberapa kali dalam hidup kita.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5ef8b2ac-9520-4b8b-8818-649234b510f9', 'トーフグは、おなかが空いたサメに食べられそうになったことが何度もある。', 'Tahu sudah hampir dimakan hiu lapar berkali-kali.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5ef8b2ac-9520-4b8b-8818-649234b510f9', '何度同じことを言えば分かるんだ？', 'Berapa kali saya harus mengatakan hal yang sama sebelum Anda mengerti?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('53373d45-090a-43d8-aabd-a791a6361a97', 'vocabulary', '西洋', '西洋', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Gaya Barat Barat masih dikenal dengan sebutan Barat. Hal yang dirujuk semua orang di Asia ketika mereka berbicara tentang negara-negara Barat di Eropa dan Amerika Utara. Di sinilah Anda akan mendengar orang mengatakan Anda berasal jika Anda tinggal di Kanada atau semacamnya.', 'Gaya Barat Barat masih dikenal dengan sebutan Barat. Hal yang dirujuk semua orang di Asia ketika mereka berbicara tentang negara-negara Barat di Eropa dan Amerika Utara. Di sinilah Anda akan mendengar orang mengatakan Anda berasal jika Anda tinggal di Kanada atau semacamnya.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
