INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('53373d45-090a-43d8-aabd-a791a6361a97', '西洋には、トーフグのファンはどのぐらいいますか。', 'Berapa banyak penggemar Tofugu di Barat?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('53373d45-090a-43d8-aabd-a791a6361a97', '西洋の国々にくらべて、インドのりこんりつはとても低い。', 'India memiliki tingkat perceraian yang sangat rendah dibandingkan negara-negara Barat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('53373d45-090a-43d8-aabd-a791a6361a97', 'これは、西洋の妖怪です。', 'Itu adalah hantu Barat.') ON CONFLICT DO NOTHING;
